import { Component, input } from '@angular/core';
import { NzCommentModule } from 'ng-zorro-antd/comment';
import { NzAvatarModule } from 'ng-zorro-antd/avatar';

/**
 * hrm-comment — bình luận (author + time + nội dung).
 *
 * Slots:
 * - default: nội dung bình luận (text hoặc markup).
 * - `<nz-comment-action>`: từng hành động dưới bình luận (Trả lời, Thích…).
 * - `<hrm-comment>` lồng bên trong: bình luận phản hồi (nested reply), tự thụt vào.
 *
 * Avatar: `avatarSrc` (ảnh) ưu tiên hơn `avatarText` (chữ viết tắt).
 */
@Component({
  selector: 'hrm-comment',
  imports: [NzCommentModule, NzAvatarModule],
  template: `
    <nz-comment [nzAuthor]="author()" [nzDatetime]="datetime()">
      @if (avatarSrc()) {
        <nz-avatar nz-comment-avatar [nzSrc]="avatarSrc()"></nz-avatar>
      } @else {
        <nz-avatar nz-comment-avatar [nzText]="avatarText()"></nz-avatar>
      }
      <nz-comment-content><ng-content /></nz-comment-content>
      <ng-content select="nz-comment-action" />
      <ng-content select="hrm-comment" />
    </nz-comment>
  `,
  host: { class: 'hrm-comment' },
})
export class HrmComment {
  readonly author = input('');
  readonly datetime = input('');
  readonly avatarText = input('');
  readonly avatarSrc = input('');
}
